PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS spaces(id TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS dormitories(id TEXT PRIMARY KEY,name TEXT NOT NULL);
INSERT OR IGNORE INTO dormitories VALUES ('A','A기숙사'),('B','B기숙사');
CREATE TABLE IF NOT EXISTS profiles(id INTEGER PRIMARY KEY,space TEXT NOT NULL REFERENCES spaces,handle TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('student','admin')),notify INTEGER NOT NULL DEFAULT 1,UNIQUE(space,handle));
CREATE TABLE IF NOT EXISTS dormitory_memberships(uid INTEGER PRIMARY KEY REFERENCES profiles,dorm TEXT NOT NULL REFERENCES dormitories);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,uid INTEGER NOT NULL REFERENCES profiles,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS group_buys(id INTEGER PRIMARY KEY,owner INTEGER NOT NULL REFERENCES profiles,dorm TEXT NOT NULL REFERENCES dormitories,status TEXT NOT NULL CHECK(status IN ('open','full','pending','ordered','shipping','ready','done','failed','stopped')),mode TEXT NOT NULL CHECK(mode IN ('equal','units')),lots INTEGER NOT NULL CHECK(lots>0),deadline INTEGER NOT NULL,order_at INTEGER NOT NULL,created INTEGER NOT NULL,filled INTEGER,closed INTEGER,checklist INTEGER NOT NULL DEFAULT 0,kakao TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS group_buy_items(buy INTEGER PRIMARY KEY REFERENCES group_buys,name TEXT NOT NULL,image TEXT NOT NULL,url TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>0),qty INTEGER NOT NULL CHECK(qty>0),category TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pickup_schedules(buy INTEGER PRIMARY KEY REFERENCES group_buys,place TEXT NOT NULL,at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS group_buy_participants(id INTEGER PRIMARY KEY,buy INTEGER NOT NULL REFERENCES group_buys,uid INTEGER NOT NULL REFERENCES profiles,lots INTEGER NOT NULL CHECK(lots>0),active INTEGER DEFAULT 1,amount INTEGER DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS unique_active ON group_buy_participants(buy,uid) WHERE active=1;
CREATE TABLE IF NOT EXISTS payment_simulations(pid INTEGER PRIMARY KEY REFERENCES group_buy_participants,status TEXT NOT NULL CHECK(status IN ('demo','void')));
CREATE TABLE IF NOT EXISTS orders(buy INTEGER PRIMARY KEY REFERENCES group_buys,recorded_by INTEGER REFERENCES profiles,at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pickup_confirmations(pid INTEGER PRIMARY KEY REFERENCES group_buy_participants,student_at INTEGER,host_at INTEGER,host_uid INTEGER REFERENCES profiles);
CREATE TABLE IF NOT EXISTS chat_rooms(buy INTEGER PRIMARY KEY REFERENCES group_buys);
CREATE TABLE IF NOT EXISTS chat_messages(id INTEGER PRIMARY KEY,buy INTEGER NOT NULL REFERENCES chat_rooms,uid INTEGER NOT NULL REFERENCES profiles,body TEXT NOT NULL,at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,uid INTEGER NOT NULL REFERENCES profiles,buy INTEGER REFERENCES group_buys,body TEXT NOT NULL,at INTEGER NOT NULL,seen INTEGER DEFAULT 0,dedupe TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS cancellation_requests(id INTEGER PRIMARY KEY,pid INTEGER NOT NULL REFERENCES group_buy_participants,at INTEGER NOT NULL,result TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS issue_reports(id INTEGER PRIMARY KEY,buy INTEGER NOT NULL REFERENCES group_buys,uid INTEGER NOT NULL REFERENCES profiles,kind TEXT NOT NULL,body TEXT NOT NULL,photo TEXT,status TEXT NOT NULL DEFAULT 'open',result TEXT DEFAULT '',at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY,buy INTEGER REFERENCES group_buys,uid INTEGER REFERENCES profiles,event TEXT NOT NULL,at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS credentials(uid INTEGER PRIMARY KEY REFERENCES profiles, salt TEXT NOT NULL, digest TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(handle TEXT PRIMARY KEY,attempts INTEGER NOT NULL,until INTEGER NOT NULL);
